/** This channel supports one exact concrete Consent information step, not arbitrary applicability facts. */
export const resolveNoticePresentationScope = (
  notice: PrivacyNoticeVersion,
  target: NoticePresentationRequest,
  observedAt: string,
) => {
  const { facts } = notice.applicableScope;
  const dimensions = [
    'PRIVACY_SUBJECT',
    'CONTROLLER_SCOPE',
    'PROCESSING_PURPOSE',
    'PROCESSING_PURPOSE_VERSION',
  ] as const;
  const fact = (dimension: (typeof dimensions)[number]) => {
    const rows = facts.filter((item) => item.dimension === dimension);
    return rows.length === 1 ? rows[0]?.value : undefined;
  };
  const controllerRef = fact('CONTROLLER_SCOPE');
  const processingPurposeRef = fact('PROCESSING_PURPOSE');
  const purposeVersionId = fact('PROCESSING_PURPOSE_VERSION');
  const scopeMatches =
    notice.versionId === target.noticeVersionId &&
    notice.applicableScope.operation === 'CONSENT_DECISION' &&
    facts.length === dimensions.length &&
    fact('PRIVACY_SUBJECT') === target.privacySubjectRef.resourceId &&
    controllerRef !== undefined &&
    processingPurposeRef !== undefined &&
    purposeVersionId !== undefined &&
    Schema.is(Schema.String.check(Schema.isUUID()))(purposeVersionId);
  const effective =
    (comparePrivacyNoticeInstants(notice.effectiveFrom, observedAt) ?? Number.NaN) <= 0 &&
    (notice.effectiveTo === null || (comparePrivacyNoticeInstants(observedAt, notice.effectiveTo) ?? Number.NaN) < 0);
  if (!scopeMatches || !effective || notice.wording === null) {
    return Effect.fail(
      new PrivacyNoticeAcknowledgementError({
        code: 'privacy_notice_acknowledgement_invalid',
        reason:
          'The exact inline Notice is not effective or its applicability is unsupported for this information step',
      }),
    );
  }
  return Effect.succeed({ controllerRef, processingPurposeRef, purposeVersionId });
};
